    @staticmethod
    def _baseline_ids(run_dir: Any, params: Mapping[str, Any]) -> list[str]:
        configured = [str(item) for item in (params.get("baseline_booking_ids") or [])]
        if not run_dir:
            return configured
        path = Path(run_dir) / "opentrip_baseline.json"
        if not path.exists():
            return configured
        payload = json.loads(path.read_text(encoding="utf-8"))
        observed = [str(item) for item in (payload.get("booking_ids") or [])]
        if configured and observed != configured:
            raise RuntimeError(f"baseline artifact IDs differ from task params: {observed} != {configured}")
        return observed or configured

    @classmethod
    def _check_session(cls, checks: list[dict[str, Any]], failures: list[str], actual: Mapping[str, Any], expected: Mapping[str, Any]) -> None:
        user = actual.get("user") if isinstance(actual.get("user"), Mapping) else {}
        observed = {"logged_in": bool(actual.get("loggedIn")), "phone": user.get("phone"), "name": user.get("name")}
        passed = (
            observed["logged_in"] == bool(expected.get("logged_in", True))
            and str(observed.get("phone") or "") == str(expected.get("phone") or "")
            and str(observed.get("name") or "") == str(expected.get("name") or "")
        )
        cls._add_check(checks, failures, "session", passed, dict(expected), observed, "OpenTrip session does not match Lucas Lin")

    @staticmethod
    def _value_at(payload: Mapping[str, Any], path: str) -> Any:
        value: Any = payload
        for part in path.split("."):
            if not isinstance(value, Mapping):
                return None
            value = value.get(part)
        return value

    @classmethod
    def _match_required_booking(cls, expected: Mapping[str, Any], bookings: list[dict[str, Any]], baseline_ids: list[str]) -> dict[str, Any]:
        field_paths = {
            "type": "type", "status": "status", "note": "note", "contact_phone": "contactPhone",
            "item_id": "item.id", "airline": "item.airline", "flight_no": "item.flightNo",
            "flight_from": "item.from", "flight_to": "item.to", "flight_date": "item.date",
            "traveler_id": "traveler.id", "traveler_name": "traveler.name",
            "traveler_document_type": "traveler.documentType", "cabin": "cabin",
            "baggage_addon_id": "baggageAddOn.id", "hotel_name": "item.name",
            "room_id": "room.id", "room_name": "room.name", "check_in": "checkIn",
            "check_out": "checkOut", "guests": "guests", "payment_id": "payment.id",
            "payment_label": "payment.label", "base_fare": "charges.baseFare",
            "service_fee": "charges.serviceFee", "addon_fee": "charges.addOnFee", "total": "charges.total",
        }
        identity_candidates = [
            booking for booking in bookings
            if str(booking.get("type") or "") == str(expected.get("type") or "")
            and str(booking.get("note") or "") == str(expected.get("note") or "")
        ]
        if len(identity_candidates) != 1:
            return {
                "matched": False,
                "label": expected.get("label"),
                "identity_match_count": len(identity_candidates),
                "candidate_ids": [item.get("id") for item in identity_candidates],
                "failure_reason": f"expected exactly one booking for type/note identity, got {len(identity_candidates)}",
            }
        booking = identity_candidates[0]
        mismatches: list[dict[str, Any]] = []
        for key, path in field_paths.items():
            if key not in expected:
                continue
            actual_value = cls._value_at(booking, path)
            expected_value = expected.get(key)
            if isinstance(expected_value, (int, float)) and not isinstance(expected_value, bool):
                equal = float(actual_value) == float(expected_value) if actual_value is not None else False
            else:
                equal = str(actual_value) == str(expected_value)
            if not equal:
                mismatches.append({"field": key, "path": path, "expected": expected_value, "actual": actual_value})

        booking_id = str(booking.get("id") or "")
        if not booking_id.startswith(str(expected.get("id_prefix") or "OT")):
            mismatches.append({"field": "id_prefix", "expected": expected.get("id_prefix") or "OT", "actual": booking_id})
        if booking_id.startswith("OT-SEED-") or booking_id in baseline_ids:
            mismatches.append({"field": "new_booking_id", "expected": "generated non-baseline ID", "actual": booking_id})
        created_after = str(expected.get("created_after") or "")
        if created_after:
            try:
                actual_time = datetime.fromisoformat(str(booking.get("createdAt") or "").replace("Z", "+00:00"))
                cutoff = datetime.fromisoformat(created_after.replace("Z", "+00:00"))
                if actual_time <= cutoff:
                    mismatches.append({"field": "created_after", "expected": created_after, "actual": booking.get("createdAt")})
            except Exception:
                mismatches.append({"field": "created_at_parse", "expected": created_after, "actual": booking.get("createdAt")})
        return {
            "matched": not mismatches,
            "label": expected.get("label"),
            "identity_match_count": 1,
            "booking_id": booking_id,
            "actual": compact_booking(booking),
            "mismatches": mismatches,
            "failure_reason": "booking fields differ" if mismatches else None,
        }

    @staticmethod
    def _ui_evidence(observation: Any, required_tokens: list[str]) -> Mapping[str, Any]:
        nodes = list(getattr(observation, "ui_nodes", []) or [])
        foreground_window = str(getattr(observation, "foreground_window", "") or "")
        foreground_app = str(getattr(observation, "foreground_app", "") or "")
        parts = [foreground_window, foreground_app]
        for node in nodes:
            if not isinstance(node, Mapping):
                continue
            parts.extend([str(node.get("text") or ""), str(node.get("selector") or "")])
        joined = "\n".join(part for part in parts if part)
        token_matches = {token: token in joined for token in required_tokens}
        return {
            "passed": bool(required_tokens) and all(token_matches.values()),
            "required_tokens": required_tokens,
            "token_matches": token_matches,
            "foreground_window": foreground_window,
            "foreground_app": foreground_app,
            "ui_node_count": len(nodes),
        }

    @staticmethod
    def _add_check(checks: list[dict[str, Any]], failures: list[str], name: str, passed: bool, expected: Any, actual: Any, failure_reason: str) -> None:
        check = {"name": name, "status": "PASS" if passed else "FAIL", "expected": expected, "actual": actual}
        if not passed:
            check["failure_reason"] = failure_reason
            failures.append(f"{name}: {failure_reason}")
        checks.append(check)
